import json, os, glob, re, sys
from datetime import datetime
ROOT='/root/.claude/projects/-home-user-fortress/fe616d40-a9c6-56d7-9da1-7168a172765d/subagents/workflows'
def ts(s):
    return datetime.strptime(s.replace('Z','+0000'),'%Y-%m-%dT%H:%M:%S.%f%z').timestamp()
def journal(wf):
    labels={}
    for l in open(f'{ROOT}/{wf}/journal.jsonl'):
        d=json.loads(l)
        if d.get('type')=='started':
            labels.setdefault(d['agentId'],[]).append(d.get('label'))
    return labels
def load_agent(path):
    """returns dict with calls (list of tool_use events), results (id->(ts,text)), msgs (id->(first_ts,last_ts,usage))"""
    calls=[]; results={}; msgs={}; order=[]
    for l in open(path):
        try: d=json.loads(l)
        except: continue
        t=d.get('type'); 
        if 'timestamp' not in d: continue
        T=ts(d['timestamp'])
        m=d.get('message')
        if t=='assistant' and isinstance(m,dict):
            mid=m.get('id')
            u=m.get('usage') or {}
            e=msgs.get(mid)
            if e is None:
                msgs[mid]={'first':T,'last':T,'usage':dict(u),'n':0}
                order.append(mid)
                e=msgs[mid]
            e['last']=T; e['n']+=1
            for k,v in u.items():
                if isinstance(v,(int,float)):
                    e['usage'][k]=max(e['usage'].get(k,0),v)
            c=m.get('content')
            if isinstance(c,list):
                for b in c:
                    if b.get('type')=='tool_use':
                        calls.append({'id':b['id'],'name':b['name'],'input':b['input'],'ts':T,'mid':mid})
        elif t=='user' and isinstance(m,dict):
            c=m.get('content')
            if isinstance(c,list):
                for b in c:
                    if b.get('type')=='tool_result':
                        cc=b.get('content')
                        if isinstance(cc,list):
                            cc=''.join(x.get('text','') for x in cc if isinstance(x,dict))
                        results[b['tool_use_id']]=(T,cc or '')
    return {'calls':calls,'results':results,'msgs':msgs,'order':order}
