import sys,re,glob,os,json,pickle
sys.path.insert(0,'.')
from load import *
from meta import *
LIBS=['AnyType','CompilerBuiltin','CompilerLibrary','CompilerAlgebra','CompilerSystem']
NOISE=re.compile(r'\s*(\{\s*echo|ARGS=|pgrep|pkill|kill|ps |git add|git commit|git push|grep|egrep|fgrep|jq|echo|printf|sed -n|head|tail|cat\b|ls\b|awk|rg|wc|git (log|commit|show|diff)|T=|D=|#|diff|test\b|\[\[?\s)')
ANT=re.compile(r'(?:^|[;&|(\s"`\'])ant\s+(?:-\S+\s+)*(compileAll|compile)(?=\s*(?:$|[>|&;)"\'`]|2>))')
FC=re.compile(r'fortress\s+compile\b')
def split_heredocs(cmd):
    """-> (lines outside heredocs, [(path or None, body)])"""
    out=[];skip=None;cur=None;path=None;docs=[]
    for line in (cmd.split('\n') if isinstance(cmd,str) else cmd):
        if skip is not None:
            if line.strip()==skip:
                docs.append((path,'\n'.join(cur)));skip=None;path=None
            else: cur.append(line)
            continue
        out.append(line)
        m=re.search(r"<<-?\s*['\"]?(\w+)['\"]?",line)
        if m:
            skip=m.group(1);cur=[]
            pm=re.search(r'(?:cat|tee)\s*(?:-a\s*)?>>?\s*(\S+)\s*<<',line) or re.search(r'(?:cat|tee)\s*(?:-a\s*)?>>?\s*(\S+)',line)
            path=pm.group(1).strip('"\'') if pm else None
    return out,docs
def joincont(lines):
    t='\n'.join(lines)
    return re.sub(r'\\\n\s*',' ',t).split('\n')
class Reg:
    def __init__(s): s.scripts={}   # basename -> list (ts,tree,body)
    def add(s,ts,path,body):
        if not path: return
        b=os.path.basename(path)
        s.scripts.setdefault(b,[]).append((ts,path,body))
    def get(s,b,ts,path_hint=None):
        c=[x for x in s.scripts.get(b,[]) if x[0]<=ts]
        if not c: return None
        if path_hint:
            for x in reversed(c):
                if x[1].endswith(path_hint) or path_hint.endswith(x[1]): return x[2]
        return c[-1][2]
FUNDEF=re.compile(r'^\s*(?:function\s+)?([A-Za-z_][\w]*)\s*\(\)\s*\{(.*)$')
def parse_funcs(lines):
    """split lines into (non-func lines, funcs dict)"""
    funcs={};rest=[];i=0
    while i<len(lines):
        l=lines[i]; m=FUNDEF.match(l)
        if m:
            name=m.group(1); first=m.group(2)
            depth=l.count('{')-l.count('}')
            body=[first] if first.strip() else []
            while depth>0 and i+1<len(lines):
                i+=1; l2=lines[i]
                depth+=l2.count('{')-l2.count('}')
                body.append(l2)
            if body and depth<=0 and body[-1].strip()=='}': body=body[:-1]
            funcs[name]=body
        else: rest.append(l)
        i+=1
    return rest,funcs
SCRIPT=re.compile(r'(?:(?:^|[;&|(]\s*|\bnohup\s+|\bbash\s+|\bsh\s+|\bsource\s+|\.\s+|\btime\s+|\btimeout\s+\d+\s+)(?:-\w+\s+)?)((?:[\w./$~{}-]*/)?[\w.-]+\.sh)\b')
LOOP=re.compile(r'for\s+(\w+)\s+in\s+([^;]+?)\s*;\s*do\s+(.*?)\s*;?\s*done\b')
def rewrite_loops(l):
    def repl(m):
        var,words,body=m.group(1),m.group(2).split(),m.group(3)
        if not words or any(re.search(r'[$*`(]',w) for w in words): return body
        out=[]
        for w in words:
            out.append(re.sub(r'\\?\$\{?'+var+r'\}?',w.replace('\\','\\\\'),body))
        return ' ; '.join(out)
    return LOOP.sub(repl,l)
SEGSPLIT=re.compile(r'\s*(?:;|&&|\|\|)\s*')
def segments(l):
    if re.match(r'\s*(for|while|until|if|case)\b',l): return [l]
    return [x for x in SEGSPLIT.split(l) if x.strip()]
FORHEAD=re.compile(r'^\s*for\s+(\w+)\s+in\s+(.*?)\s*;?\s*do\s*$')
FORHEAD2=re.compile(r'^\s*for\s+(\w+)\s+in\s+(.*?)\s*;?\s*$')
def unroll(lines):
    out=[];i=0
    while i<len(lines):
        l=lines[i]
        m=FORHEAD.match(l); start=i+1
        if not m:
            m2=FORHEAD2.match(l)
            if m2 and i+1<len(lines) and lines[i+1].strip()=='do':
                m=m2; start=i+2
        if m:
            depth=1;j=start;body=[]
            while j<len(lines):
                t=lines[j].strip()
                if re.match(r'(for|while|until)\b',t) and not t.endswith('done'): depth+=1
                if t=='done' or t.startswith('done '):
                    depth-=1
                    if depth==0: break
                body.append(lines[j]); j+=1
            var=m.group(1); words=m.group(2).split()
            n=1 if (not words or any(re.search(r'[$*`(]',w) for w in words)) else len(words)
            body=unroll(body)
            if n==1 and len(words)!=1:
                out+=body
            else:
                for w in words:
                    out+=[re.sub(r'\$\{?'+var+r'\}?',w.replace('\\','\\\\'),bl) for bl in body]
            i=j+1
        else:
            out.append(l); i+=1
    return out
def expand(lines,ts,reg,funcs,depth=0):
    out=[]
    if depth>4: return out
    lines=joincont(lines)
    rest,f2=parse_funcs(lines)
    rest=unroll(rest)
    funcs.update(f2)
    for l0 in rest:
        l0=rewrite_loops(l0)
        for l in segments(l0):
            if NOISE.match(l) or 'facts-extract' in l: continue
            for m in SCRIPT.finditer(l):
                p=m.group(1); b=os.path.basename(p)
                body=reg.get(b,ts,p)
                if body is not None:
                    bl,docs=split_heredocs(body.split('\n'))
                    out+=expand(bl,ts,reg,funcs,depth+1)
            for fn,body in funcs.items():
                if fn in ('run_bg','wait_for'): continue
                if re.match(r'\s*(?:\(\s*)?'+re.escape(fn)+r'(?:\s|;|$|\))',l):
                    out+=expand(body,ts,reg,funcs,depth+1)
            out.append(l)
    return out
def units_of(expl):
    units=[];cur=None
    def flush():
        nonlocal cur
        if cur: units.append(cur); cur=None
    for l in expl:
        if ANT.search(l) and not FC.search(l.split('ant')[0]):
            flush(); units.append({'k':'ant','t':ANT.search(l).group(1),'line':l.strip()[:220]})
        if FC.search(l):
            names=[n for n in LIBS if n in l]
            if '$' in l and not names:
                # loop var: look for for-line comps already seen
                pass
            if names or ('for ' in l):
                for n in names:
                    if cur is None: cur={'k':'lib','c':[],'line':l.strip()[:220]}
                    if n in cur['c']: flush(); cur={'k':'lib','c':[],'line':l.strip()[:220]}
                    cur['c'].append(n)
    flush()
    # merge loop-style: a for-line group followed by fc line
    return units
def tree_of(txt):
    m=re.search(r'/home/user/fortress[\w.-]*',txt); return m.group(0) if m else None

